!function(t){const n=function(){"use strict";const t={"study-plan":"📚 <b>Kế hoạch học tập hiệu quả:</b><br><br>1. <b>Xác định mục tiêu:</b> Bạn muốn đạt được gì? (VD: thi đỗ, học ngoại ngữ, kỹ năng mới)<br><br>2. <b>Chia nhỏ mục tiêu:</b> Chia thành các mục tiêu theo tháng/tuần trong app.<br><br>3. <b>Phân bổ thời gian:</b> Dùng Pomodoro 25 phút tập trung, 5 phút nghỉ — sau 4 lần nghỉ dài 25 phút.<br><br>4. <b>Theo dõi thói quen:</b> Tạo habit học tập trong app để theo dõi % hoàn thành và streak 🔥<br><br>5. <b>Phản ánh:</b> Cuối tuần viết reflection để xem lại tiến độ.<br><br>💡 Gợi ý: Dùng tính năng Mục tiêu năm để đặt mục tiêu lớn, Mục tiêu tháng để chia nhỏ, và Task tuần để hành động cụ thể!","goal-tips":"🎯 <b>Mẹo đạt mục tiêu:</b><br><br>1. <b>SMART goals:</b> Cụ thể, đo lường được, khả thi, liên quan, có thời hạn.<br><br>2. <b>Chia nhỏ:</b> Mục tiêu năm → tháng → tuần. App có sẵn cấu trúc này!<br><br>3. <b>Theo dõi:</b> Tick ✓ mỗi mục tiêu khi hoàn thành. App tự tính % tiến độ.<br><br>4. <b>Streak 🔥:</b> Duy trì mỗi ngày — streak càng dài càng có động lực!<br><br>5. <b>Phản ánh:</b> Viết reflection mỗi tuần/tháng để rút kinh nghiệm.<br><br>💡 Bạn có thể dùng Pull Goals từ Dashboard để tổng hợp mục tiêu từ 12 tháng!","habit-tips":'🔥 <b>Mẹo xây thói quen mới:</b><br><br>1. <b>Bắt đầu nhỏ:</b> Chỉ 1 thói quen, cực kỳ dễ (VD: đọc 1 trang sách).<br><br>2. <b>Gắn với thói quen cũ:</b> "Sau khi uống cà phê sáng, tôi sẽ đọc 1 trang sách."<br><br>3. <b>Theo dõi liên tục:</b> Tick ✓ mỗi ngày trong app, duy trì streak 🔥<br><br>4. <b>Đặt mục tiêu %:</b> Mỗi habit có target %, app tự tính. Đạt 100% là cíuu!<br><br>5. <b>Heatmap:</b> Xem heatmap tháng và năm để thấy sự tiến bộ.<br><br>💡 App có sẵn 10 thói quen mẫu — bạn có thể xoá/sửa và thêm thói quen của riêng mình!',"pomodoro-tips":"🍅 <b>Cách dùng Pomodoro hiệu quả:</b><br><br>1. <b>Chọn task:</b> Chọn 1 task cụ thể để tập trung.<br><br>2. <b>Bắt đầu timer:</b> Ấn nút 🍅, tập trung 25 phút.<br><br>3. <b>Nghỉ ngắn:</b> Hết 25 phút → nghỉ 5 phút. Đứng dậy, vươn vai.<br><br>4. <b>Lặp lại:</b> Sau 4 lần tập trung → nghỉ dài 25 phút 🧘<br><br>5. <b>Theo dõi:</b> App ghi lại số lần tập trung hôm nay và tuần này.<br><br>💡 Mẹo: Dùng Pomodoro widget ngay trong view tuần để tiện theo dõi!"};function n(){const t=document.getElementById("chatInput");if(!t)return;const n=t.value.trim();if(!n)return;t.value="";const i=document.getElementById("chatMessages");if(!i)return;const b=document.createElement("div");b.className="chat-msg user",b.innerHTML=esc(n),i.appendChild(b),setTimeout(()=>{const t=document.createElement("div");t.className="chat-msg bot",t.innerHTML=h(n),i.appendChild(t),i.scrollTop=i.scrollHeight},500),i.scrollTop=i.scrollHeight}function i(n){const i=document.getElementById("chatMessages");if(!i)return;const h=document.createElement("div");h.className="chat-msg bot",h.innerHTML=t[n]||"Cảm ơn bạn! Tôi sẽ giúp bạn học tập tốt hơn.",i.appendChild(h),i.scrollTop=i.scrollHeight}function h(n){const i=n.toLowerCase();return i.includes("kế hoạch")||i.includes("học tập")||i.includes("study")||i.includes("plan")?t["study-plan"]:i.includes("mục tiêu")||i.includes("goal")||i.includes("target")?t["goal-tips"]:i.includes("thói quen")||i.includes("habit")||i.includes("streak")||i.includes("xây")?t["habit-tips"]:i.includes("pomodoro")||i.includes("tập trung")||i.includes("focus")||i.includes("timer")||i.includes("cà chua")?t["pomodoro-tips"]:"Cảm ơn câu hỏi của bạn! 🐥<br><br>Bạn có thể tham khảo các chủ đề:<br>• 📚 <b>Lên kế hoạch học tập</b> — bấm nút gợi ý bên trên<br>• 🎯 <b>Mẹo đạt mục tiêu</b><br>• 🔥 <b>Xây thói quen mới</b><br>• 🍅 <b>Cách dùng Pomodoro</b><br><br>Hoặc gõ trực tiếp câu hỏi của bạn!"}return{CHAT_RESPONSES:t,doChatSend:n,doChatSuggest:i,chatBotReply:h}}();"undefined"!=typeof module&&module.exports?module.exports=n:t.TaskFlowChat=n}("undefined"!=typeof window?window:globalThis);